INSERT INTO public.collections ("id", "slug", "name", "description", "published", "created_at", "updated_at", "hero_image_url", "sort_order") SELECT "id", "slug", "name", "description", "published", "created_at", "updated_at", "hero_image_url", "sort_order" FROM jsonb_populate_recordset(NULL::public.collections, $catalog_collections$[{"id":"474836df-fa8e-493b-a783-739ab18dc8a4","name":"Сэвэны-хранители","slug":"seven-guardians","published":true,"created_at":"2026-08-13T12:42:59.253523+00:00","sort_order":20,"updated_at":"2026-08-16T05:25:33.373882+00:00","description":"Символические помощники, вдохновлённые культовой скульптурой Приамурья.\nЧеловека во все времена привлекали мистические истории и таинственные предметы. Одними из ярких представителей таковых являются сэвэны, большая коллекция которых представлена в Хабаровском Краевом Музее имени Н.И.Гродекова.\nКультовая скульптура бывает антропоморфной, зооморфной и абстрактно геометризованной. Визуальные образы духов, и самих культовых скульптур рождены снами шаманов, которые считались реальными путешествиями его души, и являются отражением архаичного мировоззрения их создателей. Все сэвэны служили своего рода помощниками, проводниками в мир духов, божеств и стихий. \nСегодня все истории о духах и шаманах кажутся чем-то нереальным, чем-то далеким и сказочным, но тем не менее всем хочется верить в чудеса, а может быть даже заполучить и себе верных помощников, пусть и символических.\n","hero_image_url":"https://circon3m22.github.io/je-tiki/images/je-tiki/seven-guardians.jpg"},{"id":"8d452070-cf84-4f65-ae43-747af0d10cc3","name":"Новая коллекция","slug":"new-collection","published":false,"created_at":"2026-08-16T05:21:52.345987+00:00","sort_order":40,"updated_at":"2026-08-16T05:21:52.345987+00:00","description":"","hero_image_url":null},{"id":"b32477ca-cabd-4288-88e5-7a8d4897d8b8","name":"На Пути","slug":"on-the-way","published":true,"created_at":"2026-08-13T12:42:59.253523+00:00","sort_order":30,"updated_at":"2026-08-16T05:27:40.627038+00:00","description":"Простая геометрия и живой рисунок дальневосточного дерева.\nДерево удивительный материал, самодостаточный, теплый, имеющий огромный энергетический потенциал.\nЭто материал, в рисунках которого заложен прекрасный божественный узор. Мы лишь отчищаем, шлифуем и превращаем в предмет - чтобы люди могли соприкоснуться с чем-то истинным и настоящим. Дерево лишь проводник, связь, повод – остановиться, задуматься, полюбоваться и помечтать. \n","hero_image_url":"https://circon3m22.github.io/je-tiki/images/je-tiki/triangle-on-model.webp"},{"id":"fe26e58f-b90c-4b51-9b71-9822a9e43684","name":"В ритме Амура","slug":"amur-rhythm","published":true,"created_at":"2026-08-13T12:42:59.253523+00:00","sort_order":10,"updated_at":"2026-08-16T05:24:18.327147+00:00","description":"Орнамент как современный язык великой реки и народов Приамурья.\nВеличественная река, таежный свободный дух, благородная красота бескрайних земель - позволяют жить, мыслить, двигаться в определенном ритме. Этот ритм вплетается узорами, звучит в дуновении ветра, проблескивает отражениями солнца в глади воды. \nНародам Приамурья удалось пронести этот ритм через века. Вплести его в уникальные орнаменты, которые служили не столько декоративным средством, сколько древней знаковой системой, концентрирующей в себе широкие знания всех предшествующих поколений о мире и обществе. ","hero_image_url":"https://circon3m22.github.io/je-tiki/images/je-tiki/spiral-on-model.jpg"}]$catalog_collections$::jsonb);

DO $verify$ BEGIN IF (SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY id), '[]'::jsonb) FROM public.collections t) IS DISTINCT FROM $catalog_collections$[{"id":"474836df-fa8e-493b-a783-739ab18dc8a4","name":"Сэвэны-хранители","slug":"seven-guardians","published":true,"created_at":"2026-08-13T12:42:59.253523+00:00","sort_order":20,"updated_at":"2026-08-16T05:25:33.373882+00:00","description":"Символические помощники, вдохновлённые культовой скульптурой Приамурья.\nЧеловека во все времена привлекали мистические истории и таинственные предметы. Одними из ярких представителей таковых являются сэвэны, большая коллекция которых представлена в Хабаровском Краевом Музее имени Н.И.Гродекова.\nКультовая скульптура бывает антропоморфной, зооморфной и абстрактно геометризованной. Визуальные образы духов, и самих культовых скульптур рождены снами шаманов, которые считались реальными путешествиями его души, и являются отражением архаичного мировоззрения их создателей. Все сэвэны служили своего рода помощниками, проводниками в мир духов, божеств и стихий. \nСегодня все истории о духах и шаманах кажутся чем-то нереальным, чем-то далеким и сказочным, но тем не менее всем хочется верить в чудеса, а может быть даже заполучить и себе верных помощников, пусть и символических.\n","hero_image_url":"https://circon3m22.github.io/je-tiki/images/je-tiki/seven-guardians.jpg"},{"id":"8d452070-cf84-4f65-ae43-747af0d10cc3","name":"Новая коллекция","slug":"new-collection","published":false,"created_at":"2026-08-16T05:21:52.345987+00:00","sort_order":40,"updated_at":"2026-08-16T05:21:52.345987+00:00","description":"","hero_image_url":null},{"id":"b32477ca-cabd-4288-88e5-7a8d4897d8b8","name":"На Пути","slug":"on-the-way","published":true,"created_at":"2026-08-13T12:42:59.253523+00:00","sort_order":30,"updated_at":"2026-08-16T05:27:40.627038+00:00","description":"Простая геометрия и живой рисунок дальневосточного дерева.\nДерево удивительный материал, самодостаточный, теплый, имеющий огромный энергетический потенциал.\nЭто материал, в рисунках которого заложен прекрасный божественный узор. Мы лишь отчищаем, шлифуем и превращаем в предмет - чтобы люди могли соприкоснуться с чем-то истинным и настоящим. Дерево лишь проводник, связь, повод – остановиться, задуматься, полюбоваться и помечтать. \n","hero_image_url":"https://circon3m22.github.io/je-tiki/images/je-tiki/triangle-on-model.webp"},{"id":"fe26e58f-b90c-4b51-9b71-9822a9e43684","name":"В ритме Амура","slug":"amur-rhythm","published":true,"created_at":"2026-08-13T12:42:59.253523+00:00","sort_order":10,"updated_at":"2026-08-16T05:24:18.327147+00:00","description":"Орнамент как современный язык великой реки и народов Приамурья.\nВеличественная река, таежный свободный дух, благородная красота бескрайних земель - позволяют жить, мыслить, двигаться в определенном ритме. Этот ритм вплетается узорами, звучит в дуновении ветра, проблескивает отражениями солнца в глади воды. \nНародам Приамурья удалось пронести этот ритм через века. Вплести его в уникальные орнаменты, которые служили не столько декоративным средством, сколько древней знаковой системой, концентрирующей в себе широкие знания всех предшествующих поколений о мире и обществе. ","hero_image_url":"https://circon3m22.github.io/je-tiki/images/je-tiki/spiral-on-model.jpg"}]$catalog_collections$::jsonb THEN RAISE EXCEPTION 'Restored collections differs from snapshot'; END IF; END $verify$;

INSERT INTO public.products ("id", "slug", "name", "subtitle", "description", "price", "old_price", "orderable", "status", "featured", "stock_quantity", "category_id", "material", "wood_type", "metal", "metal_fineness", "metal_weight", "dimensions", "weight", "care", "uin", "giis_data", "certificate_url", "declaration_url", "seo_title", "seo_description", "created_at", "updated_at", "collection_id") SELECT "id", "slug", "name", "subtitle", "description", "price", "old_price", "orderable", "status", "featured", "stock_quantity", "category_id", "material", "wood_type", "metal", "metal_fineness", "metal_weight", "dimensions", "weight", "care", "uin", "giis_data", "certificate_url", "declaration_url", "seo_title", "seo_description", "created_at", "updated_at", "collection_id" FROM jsonb_populate_recordset(NULL::public.products, $catalog_products$[{"id":"03773519-45b7-4ea3-accd-695b3c12e156","uin":null,"care":"Берегите дерево от воды, парфюма","name":"Сэвэн Дюли","slug":"duli","metal":"","price":300,"status":"published","weight":null,"featured":true,"material":"Мини-брелок","subtitle":"Мини-брелок","giis_data":{},"old_price":null,"orderable":true,"seo_title":null,"wood_type":"Мини-брелок","created_at":"2026-08-30T13:24:48.328871+00:00","dimensions":"","updated_at":"2026-08-30T13:26:56.058239+00:00","category_id":"f1d8da0e-2f16-4151-88c8-588ca16665f5","description":"Дюли считался хранителем домашнего очага и покровителем семьи.","metal_weight":null,"collection_id":"474836df-fa8e-493b-a783-739ab18dc8a4","metal_fineness":null,"stock_quantity":1,"certificate_url":null,"declaration_url":null,"seo_description":null},{"id":"07d2a3b4-1e6d-42d4-86b1-810662c08c1e","uin":null,"care":"Берегите дерево от воды, парфюма и прямого солнца","name":"Рыба","slug":"keta","metal":"","price":500,"status":"published","weight":null,"featured":true,"material":"","subtitle":"","giis_data":{},"old_price":null,"orderable":true,"seo_title":null,"wood_type":"","created_at":"2026-08-30T05:25:21.163696+00:00","dimensions":"","updated_at":"2026-08-30T09:45:01.26391+00:00","category_id":"e9533422-c3ca-4481-93ba-12c8a21a32c0","description":"Жизнь местных народов веками была неразрывно связана с реками — Амуром, Уссури, Сунгари. Рыболовство было основой их хозяйства: рыба давала пищу, из её кожи шили одежду и обувь, делали паруса для лодок и нитки. Неудивительно, что образ рыбы стал одним из ключевых в орнаментальном искусстве народа. Высокая плодовитость рыб ассоциировалась у нанайцев с циклом жизни, возрождением и продолжением рода.","metal_weight":null,"collection_id":"474836df-fa8e-493b-a783-739ab18dc8a4","metal_fineness":null,"stock_quantity":0,"certificate_url":null,"declaration_url":null,"seo_description":null},{"id":"08cdd5b0-c70e-41a3-8b86-7421d3e95779","uin":null,"care":"Берегите дерево от воды, парфюма","name":"Сэвэн Исэлэ (ящерица)","slug":"ysyerb","metal":"","price":300,"status":"published","weight":null,"featured":false,"material":"Массив натурального дерева","subtitle":"Мини-брелок","giis_data":{},"old_price":null,"orderable":true,"seo_title":null,"wood_type":"Мелколистный вяз, японский вяз.","created_at":"2026-08-30T13:13:31.611037+00:00","dimensions":"","updated_at":"2026-08-30T13:13:31.611037+00:00","category_id":"f1d8da0e-2f16-4151-88c8-588ca16665f5","description":"Ящерица олицетворение интуиции. Проводник между материальным и духовным мирами. Ящерица считалась существом, способным перемещаться между разными уровнями мироздания — миром живых, миром духов, миром предков. Это связано с её привычкой прятаться в норах и трещинах, появляясь и исчезая внезапно. В шаманских практиках нанайцев ящерица выступала одним из животных-помощников, защитником от злых сил, помощника в исцелении болезней","metal_weight":null,"collection_id":"474836df-fa8e-493b-a783-739ab18dc8a4","metal_fineness":null,"stock_quantity":0,"certificate_url":null,"declaration_url":null,"seo_description":null},{"id":"1440ee28-0339-4387-9382-0911ccd27ac8","uin":null,"care":"\nБерегите дерево от воды, парфюма и прямого солнца.","name":"Клык, коготь","slug":"klik","metal":" Массив натурального дерева, стальная фурнитура","price":900,"status":"published","weight":null,"featured":false,"material":"Мелколистный вяз, японский вяз.","subtitle":"","giis_data":{},"old_price":null,"orderable":true,"seo_title":null,"wood_type":"Мелколистный вяз, японский вяз.","created_at":"2026-08-30T05:03:36.727546+00:00","dimensions":"уточняются","updated_at":"2026-08-30T05:05:16.491509+00:00","category_id":"208a37d0-f97b-4056-bce9-a75e08933780","description":"Подвеска в виде клыка или когтя — это не просто украшение, а древний символ, который во многих культурах служил оберегом и способом перенять силу и качества животного.\nОбычай носить клыки и когти хищников уходит корнями в глубокую древность. Люди верили, что частичка зверя сохраняет его мощь, и, надевая такой амулет, можно перенять его храбрость, скорость, остроту чувств. Это было особенно важно для охотников и воинов: трофей из схватки с опасным зверем доказывал силу владельца и как бы передавал ему свои защитные свойства. \nСегодня такие подвески чаще носят как стильный аксессуар с этническим мотивом. Но многие по-прежнему верят в их обережную силу и вкладывают в них личный смысл.","metal_weight":null,"collection_id":"fe26e58f-b90c-4b51-9b71-9822a9e43684","metal_fineness":null,"stock_quantity":0,"certificate_url":null,"declaration_url":null,"seo_description":null},{"id":"14b6ad42-8bcd-459e-8d24-89fdba6b67a1","uin":null,"care":"","name":"Лис","slug":"fox","metal":"","price":1000,"status":"published","weight":null,"featured":true,"material":"","subtitle":"","giis_data":{},"old_price":null,"orderable":true,"seo_title":null,"wood_type":"","created_at":"2026-08-16T08:26:26.811746+00:00","dimensions":"","updated_at":"2026-08-23T01:06:08.520312+00:00","category_id":"92b16b4f-48ad-4201-b77c-f927316e3c64","description":"","metal_weight":null,"collection_id":"fe26e58f-b90c-4b51-9b71-9822a9e43684","metal_fineness":null,"stock_q